import 'express-session';

/**
 * Расширение типа сессии.
 *
 * В сессии лежит ТОЛЬКО идентификатор пользователя. Не объект User, не email, не роли:
 * всё это копия данных из БД, которая протухает молча — пользователя забанили или
 * переименовали, а сессия ещё N дней носит старое значение и раздаёт по нему доступ.
 * По userId актуальные данные достаются из репозитория на каждый запрос (SLT-16).
 *
 * `authId` из старого проекта не переносим: поле было мёртвым.
 *
 * `sessionGen` — единственное исключение из правила «в сессии только идентификатор», и
 * исключение осознанное. Это СНИМОК поколения сессий пользователя на момент входа (SLT-31):
 * не копия изменяемых данных профиля, которая молча протухает, а неизменная метка версии.
 * Guard сверяет её с актуальным поколением в Redis; расхождение означает, что сессию выпустили
 * до logout-all, и её пора обесценить. Поле опционально: сессии, выпущенные до появления
 * механизма, снимка не имеют, и обе точки чтения трактуют его отсутствие как поколение 0.
 */
declare module 'express-session' {
  interface SessionData {
    userId?: string;
    sessionGen?: number;
  }
}
